"""Convert a Markdown file to PDF with Chinese font support."""
import sys
import markdown
from weasyprint import HTML

INPUT = "D:/Friday/inbox/纪要/智能纪要：Friday OS系统应用讨论 2026-06-09.md"
OUTPUT = "D:/Friday/inbox/纪要/智能纪要：Friday OS系统应用讨论 2026-06-09.pdf"

CSS = """
@page {
    size: A4;
    margin: 2cm;
    @bottom-center {
        content: counter(page);
        font-family: 'Microsoft YaHei', sans-serif;
        font-size: 9pt;
        color: #999;
    }
}

body {
    font-family: 'Microsoft YaHei', 'SimHei', sans-serif;
    font-size: 11pt;
    line-height: 1.8;
    color: #222;
}

h1 {
    font-size: 18pt;
    border-bottom: 2px solid #1F4E79;
    padding-bottom: 6px;
    margin-top: 24px;
    color: #1F4E79;
}

h2 {
    font-size: 14pt;
    margin-top: 20px;
    color: #2B5797;
